record.field:
for rec in records:
    values = {}

    if not rec.x_intake_reference:
        values['x_intake_reference'] = env['ir.sequence'].next_by_code('x_hr.pool') or 'MCEP-HR-F1-0001'

    if not rec.x_name:
        arabic_parts = [part for part in [rec.x_first_name_ar, rec.x_middle_names_ar, rec.x_surname_ar] if part]
        english_parts = [part for part in [rec.x_first_name_en, rec.x_middle_names_en, rec.x_surname_en] if part]
        display_parts = arabic_parts or english_parts
        if display_parts:
            values['x_name'] = ' '.join(display_parts).strip()

    if values:
        rec.sudo().write(values)

for rec in records:
    values = {}

    selected = rec.x_residence_location_id
    municipality = False
    district = False
    region = False

    if selected:
        if selected.x_location_type == 'locality':
            municipality = selected.x_parent_id
        elif selected.x_location_type == 'municipality':
            municipality = selected

        if municipality and municipality.x_location_type == 'municipality':
            district = municipality.x_parent_id

        if district and district.x_location_type == 'district':
            region = district.x_parent_id

    new_municipality_id = municipality.id if municipality and municipality.x_location_type == 'municipality' else False
    new_district_id = district.id if district and district.x_location_type == 'district' else False
    new_region_id = region.id if region and region.x_location_type == 'region' else False

    if rec.x_residence_municipality_id.id != new_municipality_id:
        values['x_residence_municipality_id'] = new_municipality_id
    if rec.x_residence_district_id.id != new_district_id:
        values['x_residence_district_id'] = new_district_id
    if rec.x_residence_region_id.id != new_region_id:
        values['x_residence_region_id'] = new_region_id

    if values:
        rec.sudo().write(values)

